// 1. Ambil memory status sebelumnya
let lastState = context.get('lastMotorState') || {};

let currentData = msg.payload; // Array input data motor
let newlyTurnedOn = [];
let currentState = {};

// 2. Loop data untuk deteksi perubahan status & siapkan baris tabel HTML
let tableRowsHtml = '';

currentData.forEach(motor => {
    let id = motor.motorId;
    let isOn = motor.isOn;

    currentState[id] = isOn;

    // Cek apakah motor BARU SAJA menyala (state change dari false ke true)
    let wasOn = lastState[id] || false;
    if (isOn && !wasOn) {
        newlyTurnedOn.push(id);
    }

    // Styling badge berdasarkan status isOn
    let statusBadge = isOn 
        ? `<span style="background-color: #2e7d32; color: white; padding: 4px 8px; border-radius: 4px; font-weight: bold; font-size: 12px;">NYALA (ON)</span>`
        : `<span style="background-color: #757575; color: white; padding: 4px 8px; border-radius: 4px; font-size: 12px;">MATI (OFF)</span>`;

    let rowBg = isOn ? '#f1f8e9' : '#ffffff';

    // Tambahkan baris tabel untuk setiap motor
    tableRowsHtml += `
        <tr style="background-color: ${rowBg}; text-align: center;">
            <td style="padding: 10px; border: 1px solid #e0e0e0; font-weight: bold;">Motor ${id}</td>
            <td style="padding: 10px; border: 1px solid #e0e0e0;">${statusBadge}</td>
        </tr>
    `;
});

// Update memory status terbaru
context.set('lastMotorState', currentState);

// 3. Jika TIDAK ada motor yang baru menyala, hentikan flow (tidak spam email)
if (newlyTurnedOn.length === 0) {
    return null;
}

// 4. Buat Subjek dan HTML Template jika ada yang baru menyala
msg.topic = `🚨 ALERT: Motor ${newlyTurnedOn.join(', ')} Menyala!`;

msg.payload = `
  <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e0e0e0; border-radius: 8px; overflow: hidden; box-shadow: 0 2px 5px rgba(0,0,0,0.1);">

    <!-- Header -->
    <div style="background-color: #d32f2f; color: #ffffff; padding: 16px; text-align: center;">
      <h2 style="margin: 0; font-size: 20px;">Pemberitahuan Status Motor</h2>
      <p style="margin: 5px 0 0 0; font-size: 13px; opacity: 0.9;">${new Date().toLocaleString('id-ID')}</p>
    </div>

    <!-- Body Content -->
    <div style="padding: 20px; color: #333333;">
      <p style="margin-top: 0;">Halo Admin,</p>

      <!-- Highlight Motor yang Baru Menyala -->
      <div style="background-color: #ffebee; border-left: 4px solid #d32f2f; padding: 12px; margin-bottom: 20px;">
        <strong style="color: #c62828;">Motor Terdeteksi Baru Menyala:</strong><br>
        <span style="font-size: 18px; font-weight: bold; color: #b71c1c;">Motor ${newlyTurnedOn.join(', ')}</span>
      </div>

      <!-- Tabel Ringkasan Seluruh Motor -->
      <p style="margin-bottom: 8px; font-weight: bold;">Ringkasan Status Seluruh Perangkat:</p>
      <table style="width: 100%; border-collapse: collapse; margin-top: 8px;">
        <thead>
          <tr style="background-color: #f5f5f5; color: #555;">
            <th style="padding: 8px; border: 1px solid #e0e0e0;">Nama Device</th>
            <th style="padding: 8px; border: 1px solid #e0e0e0;">Status Saat Ini</th>
          </tr>
        </thead>
        <tbody>
          ${tableRowsHtml}
        </tbody>
      </table>
    </div>

    <!-- Footer -->
    <div style="background-color: #f9f9f9; padding: 12px; text-align: center; font-size: 12px; color: #777; border-top: 1px solid #e0e0e0;">
      Notifikasi Otomatis Node-RED System
    </div>
  </div>
`;

const email = env.get("EMAIL_USER");
const password = env.get("EMAIL_PASS");

msg.credential = {
  "email" : email,
  "password" : password
}

return msg;

// msg.payload berisi Array [register_0, register_1]
let rawData = msg.payload;

if (!Array.isArray(rawData) || rawData.length < 2) {
    return null;
}

let gasPPM = rawData[0];
// Di Python dikali 100, jadi di sini dibagi 100
let gasPressure = parseFloat((rawData[1] / 100).toFixed(2));

// Output 1: PPM ke MQTT Gas PPM
// Output 2: Pressure ke MQTT Gas Pressure
return [
    { payload: gasPPM, topic: "gasPPM" },      // Output 1
    { payload: gasPressure, topic: "gasPressure" } // Output 2
];

// msg.payload berisi Array [bool0, bool1, bool2, bool3, bool4, bool5]
let rawCoils = msg.payload;

if (!Array.isArray(rawCoils)) {
    return null;
}

let motorStatusPayloads = [];
for (let i = 0; i < rawCoils.length; i++) {
    motorStatusPayloads.push({
        motorId: i + 1,
        isOn: Boolean(rawCoils[i])
    });
}

return { payload: motorStatusPayloads, topic: "motors" };

let data = msg.payload || {};

let gasPPM = Number(data.gasPPM) || 0;
let gasPressure = Number(data.gasPressure) || 0;
let motors = data.motors || [];

let points = [];

// 1. Point Gas Sensors
points.push({
    measurement: "gas_sensors",
    fields: {
        ppm: parseInt(gasPPM, 10),
        pressure: parseFloat(gasPressure.toFixed(2))
    },
    tags: {
        location: "Factory_Floor_1",
        device: "Siemens_LOGO"
    }
});

// 2. Point Status Motor
if (Array.isArray(motors)) {
    motors.forEach(m => {
        points.push({
            measurement: "motor_status",
            fields: { status: m.isOn ? 1 : 0 },
            tags: { motor_id: `Motor_${m.motorId}` }
        });
    });
}

msg.payload = points;

return msg;
